package com.familyfund.event.internal.entity;

import com.familyfund.event.api.dto.TaskAlertLevel;
import jakarta.persistence.*;
import lombok.*;

import java.time.Instant;

/**
 * Entity mapping table `task_progress_alerts` (Flyway V1).
 * Append-only log of automatic progress warnings generated by the background deadline
 * scanner for unfinished event tasks (US-08).
 *
 * <p>One row = one notification actually issued. The presence of a row for
 * ({@code task_id}, {@link TaskAlertLevel#Reminder24H}) is what makes the scan idempotent:
 * a task is never warned twice for the same deadline window.</p>
 */
@Entity
@Table(name = "task_progress_alerts")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class TaskProgressAlert {

    @Id
    @Column(name = "alert_id", length = 20, nullable = false, updatable = false)
    private String alertId;

    @Column(name = "task_id", length = 20, nullable = false, updatable = false)
    private String taskId;

    @Enumerated(EnumType.STRING)
    @Column(name = "alert_level", length = 25, nullable = false, updatable = false)
    private TaskAlertLevel alertLevel;

    @Column(name = "recipient_account_id", length = 20, nullable = false, updatable = false)
    private String recipientAccountId;

    @Column(name = "alert_content", columnDefinition = "TEXT", nullable = false)
    private String alertContent;

    @Column(name = "sent_time", updatable = false)
    private Instant sentTime;

    @Column(name = "is_read")
    @Builder.Default
    private Boolean isRead = Boolean.FALSE;

    @PrePersist
    public void prePersist() {
        if (this.sentTime == null) {
            this.sentTime = Instant.now();
        }
        if (this.isRead == null) {
            this.isRead = Boolean.FALSE;
        }
    }
}